static void
p(mrb_state *mrb, mrb_value obj, int prompt)
{
mrb_value val;
char* msg;

val = mrb_funcall(mrb, obj, "inspect", 0);
if (prompt) {
if (!mrb->exc) {
fputs(" => ", stdout);
}
else {
val = mrb_funcall(mrb, mrb_obj_value(mrb->exc), "inspect", 0);
}
}
if (!mrb_string_p(val)) {
val = mrb_obj_as_string(mrb, obj);
}
msg = mrb_locale_from_utf8(RSTRING_PTR(val), (int)RSTRING_LEN(val));
fwrite(msg, strlen(msg), 1, stdout);
mrb_locale_free(msg);
putc('\n', stdout);
}

/* Guess if the user might want to enter more
* or if he wants an evaluation of his code now */
static mrb_bool
is_code_block_open(struct mrb_parser_state *parser)
{
mrb_bool code_block_open = FALSE;


if (parser->parsing_heredoc != NULL) return TRUE;


if (parser->lex_strterm) return TRUE;


if (0 < parser->nerr) {
const char unexpected_end[] = "syntax error, unexpected $end";
const char *message = parser->error_buffer[0].message;






if (strncmp(message, unexpected_end, sizeof(unexpected_end) - 1) == 0) {
code_block_open = TRUE;
}
else if (strcmp(message, "syntax error, unexpected keyword_end") == 0) {
code_block_open = FALSE;
}
else if (strcmp(message, "syntax error, unexpected tREGEXP_BEG") == 0) {
code_block_open = FALSE;
}
return code_block_open;
}

switch (parser->lstate) {



case EXPR_BEG:


code_block_open = FALSE;
break;
case EXPR_DOT:


code_block_open = TRUE;
break;
case EXPR_CLASS:


code_block_open = TRUE;
break;
case EXPR_FNAME:

code_block_open = TRUE;
break;
case EXPR_VALUE:

code_block_open = TRUE;
break;



case EXPR_ARG:

code_block_open = FALSE;
break;



case EXPR_CMDARG:
break;
case EXPR_END:

break;
case EXPR_ENDARG:

break;
case EXPR_ENDFN:

break;
case EXPR_MID:

break;
case EXPR_MAX_STATE:

break;
default:

break;
}

return code_block_open;
}

struct _args {
FILE *rfp;
mrb_bool verbose : 1;
mrb_bool debug : 1;
int argc;
char** argv;
int libc;
char **libv;
};

static void
usage(const char *name)
{
static const char *const usage_msg[] = {
"switches:",
"-d set $DEBUG to true (same as `mruby -d`)",
"-r library same as `mruby -r`",
"-v print version number, then run in verbose mode",
"--verbose run in verbose mode",
"--version print the version",
"--copyright print the copyright",
NULL
};
const char *const *p = usage_msg;

printf("Usage: %s [switches]\n", name);
while (*p)
printf(" %s\n", *p++);
}

static char *
dup_arg_item(mrb_state *mrb, const char *item)
{
size_t buflen = strlen(item) + 1;
char *buf = (char*)mrb_malloc(mrb, buflen);
memcpy(buf, item, buflen);
return buf;
}

static int
parse_args(mrb_state *mrb, int argc, char **argv, struct _args *args)
{
char **origargv = argv;
static const struct _args args_zero = { 0 };

*args = args_zero;

for (argc--,argv++; argc > 0; argc--,argv++) {
char *item;
if (argv[0][0] != '-') break;

item = argv[0] + 1;
switch (*item++) {
case 'd':
args->debug = TRUE;
break;
case 'r':
if (!item[0]) {
if (argc <= 1) {
printf("%s: No library specified for -r\n", *origargv);
return EXIT_FAILURE;
}
argc--; argv++;
item = argv[0];
}
if (args->libc == 0) {
args->libv = (char**)mrb_malloc(mrb, sizeof(char*));
}
else {
args->libv = (char**)mrb_realloc(mrb, args->libv, sizeof(char*) * (args->libc + 1));
}
args->libv[args->libc++] = dup_arg_item(mrb, item);
break;
case 'v':
if (!args->verbose) mrb_show_version(mrb);
args->verbose = TRUE;
break;
case '-':
if (strcmp((*argv) + 2, "version") == 0) {
mrb_show_version(mrb);
exit(EXIT_SUCCESS);
}
else if (strcmp((*argv) + 2, "verbose") == 0) {
args->verbose = TRUE;
break;
}
else if (strcmp((*argv) + 2, "copyright") == 0) {
mrb_show_copyright(mrb);
exit(EXIT_SUCCESS);
}
default:
return EXIT_FAILURE;
}
}

if (args->rfp == NULL) {
if (*argv != NULL) {
args->rfp = fopen(argv[0], "r");
if (args->rfp == NULL) {
printf("Cannot open program file. (%s)\n", *argv);
return EXIT_FAILURE;
}
argc--; argv++;
}
}
args->argv = (char **)mrb_realloc(mrb, args->argv, sizeof(char*) * (argc + 1));
memcpy(args->argv, argv, (argc+1) * sizeof(char*));
args->argc = argc;

return EXIT_SUCCESS;
}

static void
cleanup(mrb_state *mrb, struct _args *args)
{
if (args->rfp)
fclose(args->rfp);
mrb_free(mrb, args->argv);
if (args->libc) {
while (args->libc--) {
mrb_free(mrb, args->libv[args->libc]);
}
mrb_free(mrb, args->libv);
}
mrb_close(mrb);
}


static void
print_hint(void)
{
printf("mirb - Embeddable Interactive Ruby Shell\n\n");
