static int
check_keyword(const char *buf, const char *word)
{
const char *p = buf;
size_t len = strlen(word);


while (*p && ISSPACE(*p)) {
p++;
}

if (strncmp(p, word, len) != 0) {
return 0;
}
p += len;

while (*p) {
if (!ISSPACE(*p)) return 0;
p++;
}
return 1;
}


